65	export default function MapView({ token, onTokenExpired }) {
66	  const [track, setTrack] = useState(null);
67	  const [location, setLocation] = useState(null);
68	  const [status, setStatus] = useState("loading");
69	  const [controlMessage, setControlMessage] = useState(null);
70	  const [exploreMode, setExploreMode] = useState(false);
71	  const lastArtistRef = useRef(null);
72	  const refreshingRef = useRef(false);
73	  const mountedRef = useRef(true);
74	
75	  // Runs unconditionally from app boot regardless of exploreMode, per spec —
76	  // the background resolution loop keeps the library pre-populated so
77	  // explore mode is ready by the time the user opens it.
78	  const { artists, resolvedCount, total, scopeMissing, failedCount } =
79	    useLibraryArtists(token);
80	
81	  useEffect(() => {
82	    mountedRef.current = true;
83	    return () => {
84	      mountedRef.current = false;
85	    };
86	  }, []);
87	
88	  // Surfaces a stale-scope 403 (a session authorized before `user-follow-read`
89	  // was added — see the design doc's migration note) alongside the existing
90	  // transient controlMessage, without storing it in that same state. It's a
91	  // *persistent* condition (stays true until the user re-logs-in) riding on
92	  // a channel (`controlMessage`) that `runControl` unconditionally clears on
93	  // every successful play/pause/skip/select — storing the warning there
94	  // caused it to be silently wiped out by the next unrelated successful
95	  // control action. Deriving it instead means there's no state for anything
96	  // to clobber: a transient control error still wins while it's showing
97	  // (matches existing single-message-slot UI), and the scope warning simply
98	  // reappears on its own once that transient message clears, because
99	  // `scopeMissing` itself hasn't changed.
100	  const displayMessage =
101	    controlMessage ?? (scopeMissing ? SCOPE_WARNING : null);
102	
103	  // Fetch the currently-playing track and update state. Throws on API error so
104	  // callers (the poll loop and the control handlers) can apply their own
105	  // error handling. Both share this so a control action can refresh instantly.
106	  const syncNowPlaying = useCallback(async () => {
107	    const current = await fetchCurrentlyPlaying(token);
108	    if (!mountedRef.current) return;
109	
110	    if (!current) {
111	      devLog("[poll] nothing playing");
112	      setStatus("idle");
113	      return;
114	    }
115	
116	    // update track immediately; location catches up asynchronously
117	    setTrack(current);
118	    setStatus("playing");
119	    devLog(`[poll] now playing: ${current.artistName} – ${current.trackName}`);
120	
121	    if (current.artistName !== lastArtistRef.current) {
122	      lastArtistRef.current = current.artistName;
123	      devLog(`[poll] artist changed, looking up ${current.artistName}`);
124	      const loc = await lookupArtistLocation(current.artistName);
125	      if (mountedRef.current) setLocation(loc ?? PACIFIC_FALLBACK);
126	    }
127	  }, [token]);
128	
129	  // Shared TOKEN_EXPIRED refresh path, guarded so only one refresh runs at a
130	  // time even across overlapping poll/control errors.
131	  const refreshToken = useCallback(async () => {
132	    if (refreshingRef.current) return;
133	    refreshingRef.current = true;
134	    devLog("[poll] token expired, refreshing");
135	    try {
136	      await onTokenExpired();
137	    } finally {
138	      refreshingRef.current = false;
139	    }
140	  }, [onTokenExpired]);
141	
142	  useEffect(() => {
143	    let cancelled = false;
144	
145	    async function poll() {
146	      if (cancelled) return;
147	      try {
148	        await syncNowPlaying();
149	      } catch (err) {
150	        if (cancelled) return;
151	        const action = classifyPollError(err.message);
152	        if (action.type === "refresh") {
153	          await refreshToken();
154	          return;
155	        }
156	        if (action.type === "retry") {
157	          devLog(`[poll] rate limited, retrying in ${action.seconds}s`);
158	          // safe to schedule even near unmount: poll() checks cancelled at the top
159	          setTimeout(poll, action.seconds * 1000);
160	          return;
161	        }
162	        console.error("[poll] error:", err.message);
163	        setStatus("error");
164	      }
165	    }
166	
167	    poll();
168	    const id = setInterval(poll, POLL_MS);
169	    return () => {
170	      cancelled = true;
171	      clearInterval(id);
172	    };
173	  }, [syncNowPlaying, refreshToken]);
174	
175	  async function runControl(action) {
176	    try {
177	      await action();
178	      setControlMessage(null);
179	      return true;
180	    } catch (err) {
181	      if (err.message === "TOKEN_EXPIRED") {
182	        await refreshToken();
183	      } else {
184	        setControlMessage("Playback control not available");
185	      }
186	      return false;
187	    }
188	  }
189	
190	  async function handlePlayPause() {
191	    const wasPlaying = track?.isPlaying;
192	    const ok = await runControl(() =>
193	      wasPlaying ? pause(token) : play(token),
194	    );
195	    if (!ok) return;
196	    // Optimistic flip so the icon updates immediately. We deliberately do NOT
197	    // re-sync here: Spotify's currently-playing read is eventually consistent
198	    // and for a moment still reports the old is_playing, which would clobber
199	    // this flip and make the button flicker back. The 5s poll reconciles.
200	    setTrack((t) => (t ? { ...t, isPlaying: !wasPlaying } : t));
201	  }
202	
203	  async function handleNext() {
204	    const ok = await runControl(() => skipToNext(token));
205	    if (!ok) return;
206	    syncNowPlaying().catch(() => {});
207	  }
208	
209	  // Starts playback of the selected library artist. Routes through the
210	  // existing runControl helper (TOKEN_EXPIRED -> refresh, other errors ->
211	  // controlMessage) rather than duplicating that handling here.
212	  // Deliberately does NOT change exploreMode: selecting an artist stays on
213	  // the clustered library view — NowPlayingCard already reflects playback
214	  // regardless of exploreMode, so there's no "switch back" transition.
215	  async function handleSelectArtist(artist) {
216	    await runControl(() =>
217	      play(token, { contextUri: `spotify:artist:${artist.id}` }),
218	    );
219	  }
220	
221	  const statusOverlayMessage =
222	    status === "idle"
223	      ? "Play something on Spotify"
224	      : status === "error"
225	        ? "Something went wrong. Check the console."
226	        : null;
227	
228	  // NowPlayingCard only exists while a track is actually playing (track can
229	  // go stale — e.g. still set from a previous "playing" poll — once status
230	  // moves to "idle"/"error", so this checks status too, not just track).
231	  // When there's no card to host displayMessage (the scope warning, or a
232	  // transient control error from selecting a library artist while nothing
233	  // is playing), it falls back to its own standalone slot so it's never
234	  // silently dropped just because playback stopped.
235	  const showNowPlayingCard = status === "playing" && track;
236	
237	  return (
238	    <div style={{ position: "relative", height: "100vh", width: "100%" }}>
239	      {/* LeafletMap only gets a track/location while status is actually
240	          "playing" (same condition as showNowPlayingCard) — track/location
241	          state itself is left untouched (syncNowPlaying's artist-change
242	          dedup and handlePlayPause's optimistic flip both still rely on it
243	          persisting across idle/error). Without this, the last-played
244	          AlbumBubble stayed pinned on the map underneath the idle/error
245	          overlay, disagreeing with the (correctly hidden) NowPlayingCard
246	          about whether that track was still current. */}
247	      <LeafletMap
248	        track={showNowPlayingCard ? track : null}
249	        location={showNowPlayingCard ? location : null}
250	        exploreMode={exploreMode}
251	        libraryArtists={artists}
252	        onSelectArtist={handleSelectArtist}
253	      />
254	      {statusOverlayMessage && (
255	        <div style={STATUS_OVERLAY_STYLE}>
256	          <p style={{ margin: 0 }}>{statusOverlayMessage}</p>
257	        </div>
258	      )}
259	      {showNowPlayingCard ? (
260	        <NowPlayingCard
261	          track={track}
262	          placeName={location?.placeName}
263	          onPlayPause={handlePlayPause}
264	          onNext={handleNext}
265	          controlMessage={displayMessage}
266	        />
267	      ) : (
268	        displayMessage && (
269	          <div style={STANDALONE_MESSAGE_STYLE}>{displayMessage}</div>
270	        )
271	      )}
272	      <LibraryLoadingBadge
273	        resolvedCount={resolvedCount}
274	        total={total}
275	        failedCount={failedCount}
276	      />
277	      <BrowseLibraryButton
278	        exploreMode={exploreMode}
279	        onToggle={() => setExploreMode((v) => !v)}
280	      />
281	    </div>
282	  );
283	}
