4	// Cancellable delay: rejects immediately (or as soon as `signal` aborts)
5	// instead of resolving, so a stale throttled-retry timer never fires a
6	// request for a loop whose effect has already been cleaned up.
7	function delay(ms, signal) {
8	  return new Promise((resolve, reject) => {
9	    if (signal.aborted) {
10	      reject(new DOMException("Aborted", "AbortError"));
11	      return;
12	    }
13	    const id = setTimeout(resolve, ms);
14	    signal.addEventListener(
15	      "abort",
16	      () => {
17	        clearTimeout(id);
18	        reject(new DOMException("Aborted", "AbortError"));
19	      },
20	      { once: true },
21	    );
22	  });
23	}
